/**
 * Makes src/admin/admin-dark.css = the dark mode of the admin panel.
 *
 *     node scripts/make-admin-dark.mjs
 *
 * It reads src/admin/admin.css and, for every rule that uses a light colour written directly in the file (white
 * cards, light grey backgrounds, dark text, pale borders ...), writes the same rule again with a dark colour,
 * under  html[data-adm-theme="dark"] . The colours that come from the --a-* variables are changed at the top of the
 * generated file. Run it again after you change admin.css, and commit both files.
 * Switch: the moon button in the admin top bar (Admin.jsx) sets  data-adm-theme  on <html>.
 */
import fs from 'node:fs';
import postcss from 'postcss';

const SRC = 'src/admin/admin.css';
const OUT = 'src/admin/admin-dark.css';

// light value -> dark value (matched as whole colour words)
const BG = {
  '#ffffff': '#17171b', '#fff': '#17171b', white: '#17171b',
  '#fafafa': '#1b1b20', '#f6f6f8': '#1b1b20', '#f8fafc': '#1b1b20',
  '#f4f4f5': '#22222a', '#f4f4f7': '#22222a', '#f1f1f4': '#22222a', '#f3f4f6': '#22222a', '#ececef': '#26262e',
  '#fff5f5': 'rgba(220,38,38,.12)', '#fffafa': 'rgba(220,38,38,.1)', '#fef2f2': 'rgba(220,38,38,.14)', '#fee2e2': 'rgba(220,38,38,.22)',
  '#fef3c7': 'rgba(217,119,6,.2)', '#fffbeb': 'rgba(217,119,6,.16)', '#fef9c3': 'rgba(234,179,8,.16)', '#fff7ed': 'rgba(234,88,12,.14)',
  '#dcfce7': 'rgba(22,163,74,.2)', '#f0fdf4': 'rgba(22,163,74,.14)', '#ecfdf5': 'rgba(22,163,74,.14)',
  'rgba(255, 255, 255, 0.85)': 'rgba(23,23,27,.88)', 'rgba(255, 255, 255, 0.94)': 'rgba(23,23,27,.94)', 'rgba(250, 250, 250, 0.96)': 'rgba(27,27,32,.96)',
};
const TEXT = {
  '#09090b': '#f4f4f5', '#18181b': '#f4f4f5', '#27272a': '#e4e4e7', '#3f3f46': '#d4d4d8', '#52525b': '#c4c4cc',
  '#991b1b': '#fca5a5', '#b91c1c': '#fca5a5', '#92400e': '#fcd34d', '#b45309': '#fcd34d', '#166534': '#86efac', '#15803d': '#86efac',
  '#713f12': '#fde68a', '#1e40af': '#93c5fd',
};
const BORDER = {
  '#e4e4e7': '#2c2c34', '#d4d4d8': '#3a3a44', '#ececef': '#2c2c34', '#f1f1f4': '#24242c', '#e5e7eb': '#2c2c34', '#f4f4f5': '#24242c',
  '#fecaca': 'rgba(220,38,38,.45)', '#fde68a': 'rgba(217,119,6,.45)', '#fcd34d': 'rgba(217,119,6,.5)',
  '#86efac': 'rgba(22,163,74,.5)', '#bbf7d0': 'rgba(22,163,74,.45)', '#a7f3d0': 'rgba(22,163,74,.45)', '#ffffff': '#2c2c34', '#fff': '#2c2c34',
};

const swap = (value, map) => {
  let out = value;
  let changed = false;
  for (const [from, to] of Object.entries(map)) {
    const re = new RegExp(`(^|[^\\w#.-])${from.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?![\\w-])`, 'gi');
    if (re.test(out)) {
      out = out.replace(re, (_, pre) => pre + to);
      changed = true;
    }
  }
  return changed ? out : null;
};

const css = fs.readFileSync(SRC, 'utf8');
const root = postcss.parse(css);
const out = postcss.root();
const PREFIX = 'html[data-adm-theme="dark"] ';

const prefixed = (selector) =>
  selector
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean)
    .map((s) => PREFIX + s)
    .join(',\n');

root.walkRules((rule) => {
  if (rule.parent && rule.parent.type === 'atrule' && /keyframes/i.test(rule.parent.name)) return;
  const decls = [];
  rule.walkDecls((d) => {
    const p = d.prop.toLowerCase();
    let v = null;
    if (/^background(-color)?$/.test(p)) {
      v = swap(d.value, BG);
      // the black buttons / number badges would vanish on a dark card: make them a lighter grey
      if (v === null && /(^|[^\w#])#09090b(?![\w-])/i.test(d.value) && /adm-btn|adm-sem-no|sya-sem-no|adm-filter|sya-filter button\.on/.test(rule.selector)) v = d.value.replace(/#09090b/gi, '#3a3a46');
    } else if (p === 'color') {
      v = swap(d.value, TEXT);
    } else if (/^border(-top|-right|-bottom|-left)?(-color)?$/.test(p) || p === 'outline') {
      v = swap(d.value, BORDER);
    }
    if (v !== null && v !== d.value) decls.push([d.prop, v, d.important]);
  });
  if (!decls.length) return;
  const clone = postcss.rule({ selector: prefixed(rule.selector) });
  decls.forEach(([prop, value, important]) => clone.append({ prop, value, important }));
  // keep it inside the same @media / @supports
  let holder = out;
  const chain = [];
  for (let p = rule.parent; p && p.type !== 'root'; p = p.parent) if (p.type === 'atrule') chain.unshift(p);
  chain.forEach((at) => {
    let found = holder.nodes && holder.nodes.find((n) => n.type === 'atrule' && n.name === at.name && n.params === at.params && n.__gen);
    if (!found) {
      found = postcss.atRule({ name: at.name, params: at.params });
      found.__gen = true;
      holder.append(found);
    }
    holder = found;
  });
  holder.append(clone);
});

const head = `/* GENERATED by scripts/make-admin-dark.mjs from admin.css - do not edit by hand. Dark mode of the admin panel. */

html[data-adm-theme="dark"] .adm-app,
html[data-adm-theme="dark"] .adm-gate,
html[data-adm-theme="dark"] .adm-toasts,
html[data-adm-theme="dark"] .adm-overlay {
  --a-bg: #0e0e11;
  --a-bg-subtle: #17171b;
  --a-card: #17171b;
  --a-line: #2c2c34;
  --a-line-strong: #3a3a44;
  --a-line-soft: #1f1f26;
  --a-text: #f4f4f5;
  --a-text-soft: #d4d4d8;
  --a-muted: #a1a1aa;
  --a-brand-soft: rgba(220, 38, 38, 0.16);
  --a-brand-border: rgba(220, 38, 38, 0.45);
  --a-ok-soft: rgba(22, 163, 74, 0.2);
  --a-warn-soft: rgba(217, 119, 6, 0.22);
  --a-shadow-xs: 0 1px 2px rgba(0, 0, 0, 0.4);
  --a-shadow: 0 2px 6px rgba(0, 0, 0, 0.35), 0 10px 26px rgba(0, 0, 0, 0.4);
  --a-shadow-lg: 0 16px 40px rgba(0, 0, 0, 0.55), 0 4px 12px rgba(0, 0, 0, 0.4);
  --a-shadow-modal: 0 32px 80px rgba(0, 0, 0, 0.7);
  color-scheme: dark;
}

/* things that use the text colour as a background (it is light now): make them a lighter grey with white text */
html[data-adm-theme="dark"] .sya-sem-no,
html[data-adm-theme="dark"] .sya-filter button.on,
html[data-adm-theme="dark"] .adm-stack td:nth-child(2) b {
  background: #3a3a46;
  border-color: #3a3a46;
  color: #ffffff;
}
html[data-adm-theme="dark"] .sya-sem.is-open .sya-sem-no {
  background: var(--a-brand);
}

/* inputs, selects and text areas of the browser */
html[data-adm-theme="dark"] .adm-app input,
html[data-adm-theme="dark"] .adm-app select,
html[data-adm-theme="dark"] .adm-app textarea,
html[data-adm-theme="dark"] .adm-overlay input,
html[data-adm-theme="dark"] .adm-overlay select,
html[data-adm-theme="dark"] .adm-overlay textarea {
  background: #1b1b20;
  color: #f4f4f5;
  border-color: #3a3a44;
}
html[data-adm-theme="dark"] .adm-app ::placeholder,
html[data-adm-theme="dark"] .adm-overlay ::placeholder {
  color: #71717a;
}
html[data-adm-theme="dark"] .adm-app pre,
html[data-adm-theme="dark"] .adm-app code {
  background: #1b1b20;
  color: #e4e4e7;
}

`;
fs.writeFileSync(OUT, head + out.toString().replace(/\n{3,}/g, '\n\n') + '\n');
console.log(`written ${OUT}: ${out.nodes.length} blocks`);
